VALUES
(1,  '기초부터 탄탄하게 가르치는 피아니스트입니다. 서울 강남구 기반으로 레슨합니다.',    '["한예종 졸업", "독일 유학 5년", "다수 콩쿠르 입상"]',          '지루한 체르니는 그만! 뉴에이지부터 클래식까지 1:1 맞춤 레슨',     '["음악대학 피아노 전공"]',         0, 0, 10, 'BOTH',    'COMPLETED', '신한은행', '110-1001-0001', '테스트튜터1',  0, 0, 0, NOW(), 'SYSTEM'),
(2,  '바이올린의 아름다운 선율을 함께 만들어봐요. 서울 마포구 홍대 인근 레슨 가능.',     '["시립교향악단 단원 역임", "레슨 경력 10년"]',                   '초보자도 3개월 만에 한 곡 마스터! 바이올린 기초 완성',             '["한국 예술 종합학교 음악원 졸업"]', 0, 0, 1,  'OFFLINE', 'COMPLETED', '국민은행', '110-1002-0002', '테스트튜터2',  0, 0, 0, NOW(), 'SYSTEM'),
(3,  '첼로의 깊은 울림을 전달하는 강사입니다. 직장인 위한 저녁 시간대 수업 가능.',       '["해외 음악제 초청 연주", "예술고등학교 출강"]',                  '직장인을 위한 힐링 첼로 클래스 (저녁 시간대 가능)',                '["서울대학교 음악대학 졸업"]',      0, 0, 1,  'BOTH',    'COMPLETED', '우리은행', '110-1003-0003', '테스트튜터3',  0, 0, 0, NOW(), 'SYSTEM'),
(4,  '통기타부터 일렉기타까지, 리듬을 즐겨보세요. 경기 분당 지역 레슨 가능합니다.',       '["실용음악과 졸업", "밴드 세션 활동 중"]',                       '한 달 만에 완성하는 통기타 코드와 스트로크',                        '["실용음악학과 기타 전공 졸업"]',   0, 0, 1,  'BOTH',    'COMPLETED', '하나은행', '110-1004-0004', '테스트튜터4',  0, 0, 0, NOW(), 'SYSTEM'),
(5,  '당신이 가진 최고의 악기, 목소리를 찾아드립니다. 인천/온라인 레슨 가능.',           '["유명 오디션 프로그램 코칭", "보컬 트레이너 경력"]',             '고음 불가 탈출! 호흡부터 발성까지 체계적인 보컬 트레이닝',          '["음악대학 성악과 졸업"]',         0, 0, 1,  'BOTH',    'COMPLETED', '농협은행', '110-1005-0005', '테스트튜터5',  0, 0, 0, NOW(), 'SYSTEM'),
(6,  '스트레스를 한 번에 날리는 파워풀한 드럼 레슨! 경기 수원 재즈 클럽 운영 중.',       '["재즈 클럽 정기 공연", "드럼 전문 아카데미 운영"]',              '박치 탈출! 기초 비트부터 화려한 필인까지',                          '["실용음악학과 드럼 전공 졸업"]',   0, 0, 1,  'OFFLINE', 'COMPLETED', '신한은행', '110-1006-0006', '테스트튜터6',  0, 0, 0, NOW(), 'SYSTEM'),
(7,  '음악의 뼈대, 베이스 기타의 매력에 빠져보세요. 대구 중구 인근 레슨.',               '["실용음악과 석사", "다수 인디 밴드 앨범 참여"]',                 '그루브가 살아있는 베이스 기타 중급/입문 레슨',                      '["실용음악학과 베이스 전공 졸업"]', 0, 0, 0,  'BOTH',    'COMPLETED', '국민은행', '110-1007-0007', '테스트튜터7',  0, 0, 0, NOW(), 'SYSTEM'),
(8,  '러시아 유학파 출신의 정통 클래식 피아노 레슨입니다. 대전 서구 레슨 가능.',         '["모스크바 국립 음악원 졸업", "독주회 10회 이상"]',               '기초부터 고급 입시까지, 정통 클래식 피아노의 정석',                 '["러시아 모스크바 국립 음악원 졸업"]', 0, 0, 0, 'BOTH',   'COMPLETED', '우리은행', '110-1008-0008', '테스트튜터8',  0, 0, 0, NOW(), 'SYSTEM'),
(9,  '딱딱한 악보 대신 리듬을 배우는 재즈 피아노입니다. 광주 동구 재즈 바 운영.',        '["실용음악과 졸업", "재즈 밴드 리더"]',                           '코드 반주부터 화려한 즉흥 연주까지! 재즈 피아노 입문',              '["버클리 음악대학 온라인 수료"]',   0, 0, 0,  'ONLINE',  'COMPLETED', '하나은행', '110-1009-0009', '테스트튜터9',  0, 0, 0, NOW(), 'SYSTEM'),
(10, '누구나 쉽고 재미있게 시작하는 성인 취미 피아노입니다. 강원 춘천 레슨 가능.',       '["음악교육 석사", "개인 레슨 경력 8년"]',                         '퇴근 후 나만의 힐링 시간, 한 달 한 곡 완성 프로젝트',              '["교육대학원 음악교육 석사"]',     0, 0, 1,  'BOTH',    'COMPLETED', '농협은행', '110-1010-0010', '테스트튜터10', 0, 0, 0, NOW(), 'SYSTEM'),
(11, '아이들의 눈높이에 맞춘 즐거운 음악 수업입니다. 강원 속초 유아 음악 전문.',         '["유아 음악 지도사 자격증 보유"]',                                 '창의력을 키워주는 어린이 놀이 피아노 레슨',                         '["유아 음악 교육 전문 자격 취득"]', 0, 0, 0,  'OFFLINE', 'COMPLETED', '신한은행', '110-1011-0011', '테스트튜터11', 0, 0, 0, NOW(), 'SYSTEM'),
(12, '마음을 울리는 서정적인 뉴에이지 연주를 가르칩니다. 경북 포항 레슨 / 온라인 가능.', '["음반 3장 발매", "작곡가 활동 중"]',                             '영화 OST, 뉴에이지 명곡 마스터 클래스',                             '["한국 음악 협회 정회원"]',        0, 0, 1,  'BOTH',    'COMPLETED', '국민은행', '110-1012-0012', '테스트튜터12', 0, 0, 0, NOW(), 'SYSTEM'),
(13, '독일 오케스트라 수석 출신의 디테일한 레슨입니다. 경북 구미 레슨 가능.',            '["독일 베를린 국립음대 졸업", "현직 오케스트라 수석"]',           '전공생 및 오케스트라 오디션 대비 심화 클래스',                      '["베를린 예술 대학교 바이올린 전공 졸업"]', 0, 0, 0, 'OFFLINE', 'COMPLETED', '우리은행', '110-1013-0013', '테스트튜터13', 0, 0, 0, NOW(), 'SYSTEM'),
(14, '바이올린은 첫 자세가 가장 중요합니다. 경북 안동 레슨, 예중/예고 입시 준비 가능.', '["음대 바이올린 전공", "청소년 오케스트라 지도"]',                '바이올린 기초 탄탄! 예쁜 소리 만들기 프로젝트',                     '["경북대학교 음악학과 바이올린 전공"]', 0, 0, 1, 'OFFLINE', 'COMPLETED', '하나은행', '110-1014-0014', '테스트튜터14', 0, 0, 0, NOW(), 'SYSTEM'),
(15, '취미로 시작해서 평생 친구가 되는 바이올린 레슨. 전북 전주 레슨 가능.',             '["레슨 경력 12년", "다수 동호회 지도"]',                          '성인 취미반 전문! 쉽고 빠르게 배우는 바이올린',                     '["전북대학교 음악대학 졸업"]',     0, 0, 0,  'BOTH',    'COMPLETED', '농협은행', '110-1015-0015', '테스트튜터15', 0, 0, 0, NOW(), 'SYSTEM'),
(16, '현악 사중주 등 앙상블 수업도 가능한 전문가입니다. 전남 순천 레슨.',                 '["실내악 앙상블 팀 운영", "대학 출강"]',                          '함께 연주하는 즐거움, 바이올린 앙상블 및 개인 레슨',                '["순천향대학교 음악학과 강사"]',   0, 0, 0,  'OFFLINE', 'COMPLETED', '신한은행', '110-1016-0016', '테스트튜터16', 0, 0, 0, NOW(), 'SYSTEM'),
(17, '입시와 콩쿠르 준비를 위한 확실한 성과 중심 레슨. 충남 천안/아산 레슨 가능.',       '["국내 유명 콩쿠르 심사위원", "예고 입시 합격자 다수 배출"]',    '확실한 실력 향상! 예중/예고/음대 입시 전문 지도',                   '["연세대학교 음악대학 바이올린 전공 졸업"]', 0, 0, 0, 'BOTH', 'COMPLETED', '국민은행', '110-1017-0017', '테스트튜터17', 0, 0, 0, NOW(), 'SYSTEM');

