INSERT IGNORE INTO user_role (user_id, role_id, created_at, created_by)
SELECT ua.id, r.role_id, NOW(), 'SYSTEM'
FROM user_account ua
JOIN role r ON r.role_type = 'TUTOR'
WHERE ua.id BETWEEN 101 AND 1100;

INSERT INTO tutor_account (tutor_id, introduction, experiences, title, educations, average_rating, review_count, matching_count, lesson_type, profile_status, bank_name, bank_account_number, bank_account_holder, is_birth_date_public, is_email_public, is_phone_number_public, created_at, created_by)
VALUES
(101, '안녕하세요. 음악을 사랑하는 전문 튜터101입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 4년", "전문 연주자 활동"]', '어렵고 지루한 이론 대신 귀와 손이 먼저 반응하는 실전 기타 레슨', '["음악대학 전공 졸업"]', 4.6, 1, 2, 'OFFLINE', 'COMPLETED', '국민은행', '110-0101-0001', '튜터101', 0, 0, 0, NOW(), 'SYSTEM'),
(102, '안녕하세요. 음악을 사랑하는 전문 튜터102입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 5년", "전문 연주자 활동"]', '퇴근 후 나만의 힐링 보컬 음악 시간, 누구나 쉽게 시작해요', '["음악대학 전공 졸업"]', 4.7, 2, 4, 'BOTH', 'COMPLETED', '우리은행', '110-0102-0001', '튜터102', 0, 0, 0, NOW(), 'SYSTEM'),
(103, '안녕하세요. 음악을 사랑하는 전문 튜터103입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 6년", "전문 연주자 활동"]', '신나는 드럼 비트로 스트레스 해소 및 리듬 완성', '["음악대학 전공 졸업"]', 4.8, 3, 6, 'ONLINE', 'COMPLETED', '하나은행', '110-0103-0001', '튜터103', 0, 0, 0, NOW(), 'SYSTEM'),
